#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double t;
    cin >> n >> t;

    vector<vector<double>> a(n + 1, vector<double>(n + 1, 0.0));
    a[0][0] = t;

    for (int y = 0; y < n; ++y) {
        for (int x = 0; x <= y; ++x) {
            if (a[x][y] > 1.0) {
                double excess = a[x][y] - 1.0;
                a[x][y] = 1.0;
                a[x][y + 1] += excess / 2.0;
                a[x + 1][y + 1] += excess / 2.0;
            }
        }
    }

    int answer = 0;
    for (int y = 0; y < n; ++y) {
        for (int x = 0; x <= y; ++x) {
            if (a[x][y] >= 1.0) {
                ++answer;
            }
        }
    }

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long double t;
    cin >> n >> t;

    vector<long double> current(1, t);
    int answer = 0;

    for (int row = 0; row < n; ++row) {
        vector<long double> next(row + 2, 0.0L);

        for (int i = 0; i <= row; ++i) {
            if (current[i] >= 1.0L) {
                ++answer;
            }

            if (current[i] > 1.0L) {
                long double excess = (current[i] - 1.0L) / 2.0L;
                next[i] += excess;
                next[i + 1] += excess;
            }
        }

        current.swap(next);
    }

    cout << answer;
    return 0;
}

