int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, t;
    cin >> n >> t;

    long long answer = 0;
    vector<long double> row(1, t);

    for (int level = 0; level < n; ++level) {
        vector<long double> next(level + 2, 0);

        for (int i = 0; i <= level; ++i) {
            if (row[i] >= 1) {
                ++answer;
            }

            if (row[i] > 1) {
                long double excess = (row[i] - 1) / 2;
                next[i] += excess;
                next[i + 1] += excess;
            }
        }

        row.swap(next);
    }

    cout << answer;
    return 0;
}

